{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "In dogs, the absolute oral bioavailability of menaquinone-4 (MK-4) from a soft-capsule formulation was 13.5% of the IV AUC, below the 20% threshold; MK-4 is the closest structural analogue (Morgan 0.6591) with a quinone head and isoprenoid side chain, and the query's longer decaprenyl chain and higher molecular weight would be expected to make absorption even more difficult.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "In humans, vitamin K1 (phylloquinone) had an absolute oral bioavailability of 56 ± 30% in CYP4F2 CC subjects, demonstrating that a lipophilic isoprenoid quinone can exceed 20%; however, its C20 side chain and lower Morgan similarity (0.3929) limit transfer to the much larger CoQ10-like query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "Phytoene, a C40 isoprenoid hydrocarbon, showed 58.5 ± 18.9% absolute bioavailability in humans, contradicting a low prediction for large lipophilic isoprenoids, but it lacks the quinone head and has a substantially lower molecular weight than the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "Lycopene, a C40 isoprenoid, showed only 0.17% systemic availability after oral tomato paste in humans, supporting low F for large lipophilic isoprenoids; although other lycopene estimates are higher, this direct low value and the shared long isoprenoid character are relevant to the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is CoQ10, an extremely lipophilic decaprenyl-substituted dimethoxybenzoquinone (MW ~863, no ionizable groups). The closest high-similarity analogue, MK-4, had an absolute oral bioavailability of only 13.5% in dogs, below the 20% threshold, and the query's longer isoprenoid chain and higher molecular weight would be expected to further impair dissolution and absorption. Although vitamin K1 and phytoene demonstrate that some lipophilic isoprenoids can be well absorbed in humans, their lower similarity and smaller size limit transfer. The weight of direct, transferable evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for CoQ10 itself in humans; the closest absolute value is from MK-4 in dogs.",
    "Lycopene bioavailability estimates vary widely (0.17% to ~24%), adding uncertainty to extrapolation from carotenoid evidence.",
    "Formulation dependence is critical for highly lipophilic compounds; the query's intrinsic F may differ from formulated products.",
    "Species differences in lipid absorption (rats vs dogs vs humans) are not fully captured by the available evidence."
  ],
  "new_evidence_assessment": [
    {
